#include "exotic/cognition/arbitration.hpp"
#include <cassert>
using namespace exotic::cognition;
int main(){MultiIntentionArbiter a;Intention learn{"i-learn","learn","c1","committed",0.85,"chosen"};Intention build{"i-build","build","c2","committed",0.80,"chosen"};Intention rest{"i-rest","rest","c3","tentative",0.55,"available"};Intention parked{"i-park","park","c4","suspended",0.90,"paused"};IntentionDemand d1{learn,0.8,0.9,0.15,0.1,{"i-build"},{}};IntentionDemand d2{build,0.75,0.85,0.2,0.2,{"i-learn"},{}};IntentionDemand d3{rest,0.3,0.4,0.1,0.05,{}, {"i-build"}};IntentionDemand d4{parked,1,1,0,0,{},{}};auto p=a.consider({d1,d2,d3,d4},1.0);assert(p.assignments.size()==4);bool cooperative=false,blocked=false,unscheduled=false;double allocated=0;for(const auto&x:p.assignments){allocated+=x.allocation;if(x.disposition==ArbitrationDisposition::Cooperate)cooperative=true;if(x.disposition==ArbitrationDisposition::Blocked)blocked=true;if(x.intention_id=="i-park"&&x.disposition==ArbitrationDisposition::Unscheduled)unscheduled=true;}assert(cooperative);assert(blocked||p.unused_capacity<0.1);assert(unscheduled);assert(allocated<=1.000001);assert(p.unused_capacity>=0);auto none=a.consider({},1.0);assert(none.assignments.empty());assert(none.unused_capacity==1.0);return 0;}
